  assert(block(old,'## Content and limits','## Artifact roles')===block(next,'## Content and limits','## Artifact roles'),'README mathematics');
  assert(block(old,'The inherited layout','## Actual authorship')===block(next,'The inherited layout','## Actual authorship'),'canonical/science/source boundaries');
