  assert(next.includes(added),'explicit documentary contributors');
  assert(block(old,'## Actual authorship','## Work actually done')===block(next.replace(added,''),'## Actual authorship','## Work actually done'),'original authorship exactly retained');
 }
 if(name==='CLAIMS_EVIDENCE.md'){
  const rows=s=>s.split('\n').filter(l=>/^\| C[1-9]/.test(l));
  assert(rows(old).length===7&&JSON.stringify(rows(old))===JSON.stringify(rows(next)),'seven full claim/evidence rows');
  assert(block(old,'The fixed author source','## Actual lifecycle')===block(next,'The fixed author source','## Actual lifecycle'),'finite protocol and evidence unchanged');
 }
 if(name==='NARRATIVE_REPORT.md'){
  assert(block(old,'## The technical story','## Evidence and experiment boundary')===block(next,'## The technical story','## Evidence and experiment boundary'),'whole narrative mathematics');
  assert(block(old,'## Evidence and experiment boundary','The [first artifact HOLD]')===block(next,'## Evidence and experiment boundary','The [first artifact HOLD]'),'finite evidence unchanged');
  assert(old.slice(old.indexOf('## Provenance and scope'))===next.slice(next.indexOf('## Provenance and scope')),'narrative provenance unchanged');
 }
 assert(next.includes('PHYSICAL_ROUND0_PENDING')&&next.includes('HOLD_EXTERNAL'),'remaining gates');
 assert(next.includes('p214_display_repair_artifact_root01/RECEPTION.md')&&next.includes('p214_display_repair_artifact_root01/PDF_ADOPTION.md')&&next.includes('p214_display_repair_artifact_root01/PDF_ADOPTION_NATIVE.json'),'all actual acceptance links');
 for(const m of next.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){
  const t=m[1];if(/^(https?:|#)/.test(t))continue;
  const q=path.resolve(path.dirname(l),t.split('#')[0]);assert(q.startsWith(process.cwd()+'/')&&fs.existsSync(q),'original-base link '+t);links++;
 }
 summaries.push({role:name,before_sha256:bhash,after_sha256:ahash,unchanged_current_live_sha256:lhash});
}
process.stdout.write(JSON.stringify({scope:'DOCUMENTARY_CLOSURE_ONLY_NO_SCIENCE_BUILD_FREEZE_OR_NEW_ARTIFACT_VERDICT',three_exact_mappings:summaries,all_original_math_finite_evidence_and_proof_authorship_preserved:true,documentary_contributors_explicit:true,local_links_resolved_at_intended_live_base:links},null,2)+'\n');
